test("转移：隐藏转移传给 AI 响应策略的公开上下文不含锁定手牌资料", async () => {
  const actor = makePlayer("actor", 0, "dawn"),
    from = makePlayer("from", 1, "dusk"),
    responder = makePlayer("responder", 2, "dusk"),
    receiver = makePlayer("receiver", 3, "dawn");
  const use = instance("transfer"), secret = { ...instance("block"), name: "绝密锁定牌" };
  actor.hand.push(use);
  from.hand.push(secret);
  responder.hand.push(instance("counter"));
  const { game }
    = makeGame([actor, from, responder, receiver], { random: () => 0 });
  let receivedContext = null;
  game.aiController.responsePolicy.shouldRespond = (_player, _type, context) => {
    receivedContext = context;
    return false;
  };
  await game.playCard(actor, use, [], { sourceId: from.id, receiverId: receiver.id, zone: "hand" });
  assert.ok(receivedContext);
  const publicContext = receivedContext.publicTransferContext;
  assert.ok(publicContext);
  assert.equal(Object.isFrozen(publicContext), true);
  for (
    const forbidden of ["card", "cardId", "definitionId", "hiddenCardName"]
  ) assert.equal(Object.hasOwn(publicContext, forbidden), false);
  const seen = new Set();
  const contains = (value, needle) => {
    if (value === needle) return true;
    if (!value || typeof value !== "object" || seen.has(value)) return false;
    seen.add(value);
    return Object.values(value).some((entry) => contains(entry, needle));
  };
  for (const secretValue of [secret, secret.id, secret.definitionId, secret.name]) {
    seen.clear();
    assert.equal(contains(receivedContext, secretValue), false);
  }
  assert.equal(publicContext.safeItemLabel, "1张牌");
});

