test("借势：响应窗口不再渲染卡牌列表且使用按钮无需选牌即可用", () => {
  const panel = {
    innerHTML: "", classList: { add() { }, remove() { } }, querySelector() { return null; }
  };
  const fake = {
    responseState: {
      request: {
        id: "leverage-ui",
        type: "leverageAssault",
        requiredCount: 1,
        legalCardIds: ["a1", "a2"],
        timeoutMs: 5000,
        presentation: {
          eventText: "事件",
          responseText: "响应说明",
          availabilityText: "需要1张「突袭」，当前有2张。",
          buttonLabel: "使用「突袭」",
          declineLabel: "拒绝"
        }
      },
      deadline: Date.now() + 5000,
      label: "使用「突袭」",
      selectedCardIds: new Set()
    },
    elements: { response_panel: panel },
    game: null,
    render() { }
  };
  UIManager.prototype.renderResponseRequest.call(fake);
  const html = panel.innerHTML;
  assert.doesNotMatch(html, /leverage-response-cards/);
  assert.doesNotMatch(html, /data-response-card-id/);
  assert.match(html, /使用「突袭」/);
  assert.match(html, /拒绝/);
  assert.match(html, /需要1张「突袭」，当前有2张/);
  assert.equal((html.match(/data-response-choice/g) ?? []).length, 2);
  assert.doesNotMatch(html, /disabled/);
});

