test("反制：针对震荡目标的反制仍可被后续反制，之后该目标继续承受效果", async () => {
  const a = makePlayer("a", 0, "dawn", "human"),
    b = makePlayer("b", 1, "dusk", "human"),
    c = makePlayer("c", 2, "dawn");
  const { game, ui }
    = makeGame(
      [a, b, c],
      {
        response: (request) => request.type === "counter" && request.legalCardIds.length >= request.requiredCount
      }
    );
  const shockwave = instance("shockwave"),
    first = instance("counter"),
    second = instance("counter"),
    hp = b.hp;
  a.hand.push(shockwave, second);
  b.hand.push(first);
  await game.playCard(a, shockwave, [b]);
  assert.equal(b.hp, hp - 1);
  assert.equal(b.hand.includes(first), false);
  assert.equal(a.hand.includes(second), false);
  assert.ok(
    ui.logs.some((message) => message === `${b.name}对${a.name}的「震荡」使用了「反制」，取消了「震荡」对${b.name}的效果。`)
  );
  assert.ok(ui.logs.some((message) => message === `${a.name}对${b.name}的「反制」使用了「反制」，取消了「反制」的效果。`));
  assert.ok(!ui.logs.some((message) => message.includes("被后续反制抵消")));
});

test("反制：两次反制后原战术牌恢复生效", async () => {
  const a = makePlayer("a", 0, "dawn", "human"),
    b = makePlayer("b", 1, "dusk", "human"),
    c = makePlayer("c", 2, "dawn", "human");
  const order = [];
  const { game, ui }
    = makeGame(
      [a, b, c],
      {
        response: (request) => (
          order.push(request.targetPlayerId), request.legalCardIds.length >= request.requiredCount
        )
      }
    );
  game.state.deck.cards.push(instance("block"), instance("charge"));
  a.hand.push(instance("harvest"));
  b.hand.push(instance("counter"));
  c.hand.push(instance("counter"));
  await game.playCard(a, a.hand[0], []);
  assert.deepEqual(order, [b.id, c.id, a.id, b.id]);
  assert.equal(a.hand.length, 2);
  assert.equal(b.hand.length, 0);
  assert.equal(c.hand.length, 0);
  assert.equal(ui.logs.filter((message) => message.includes("使用了「反制」")).length, 2);
  assert.ok(!ui.logs.some((message) => message.includes("被后续反制抵消")));
});

