test("互利：触发重洗后弃牌堆别名保持同步", async () => {
  const a = makePlayer("a", 0, "dawn", "human"),
    b = makePlayer("b", 1, "dusk"),
    c = makePlayer("c", 2, "dawn");
  const { game }
    = makeGame([a, b, c]);
  const discards = [instance("block"), instance("charge"), instance("recover")];
  for (const card of discards) game.state.deck.discard(card);
  let aliasDuringReveal = true;
  const originalShow = game.ui.showPublicPool;
  game.ui.showPublicPool = (cards) => {
    aliasDuringReveal = game.state.discardPile === game.state.deck.discardPile;
    originalShow?.(cards);
  };
  const mb = instance("mutualBenefit");
  a.hand.push(mb);
  assert.equal(await game.playCard(a, mb, []), true);
  assert.equal(aliasDuringReveal, true);
  assert.equal(game.state.deck.reshuffleCount, 1);
  assert.equal(game.state.publicCardPool.length, 0);
  assert.equal(a.hand.length, 1);
  assert.equal(b.hand.length, 1);
  assert.equal(c.hand.length, 1);
  assert.equal(game.state.deck.cards.length, 0);
  assert.equal(game.state.discardPile, game.state.deck.discardPile);
  assert.equal(game.state.discardPile.length, 1);
  assert.ok(game.state.deck.discardPile.includes(mb));
  const drafted = new Set([...a.hand, ...b.hand, ...c.hand]);
  for (const card of discards) assert.ok(drafted.has(card));
});

