  const source = makePlayer("aid-next-source", 0, "dusk", "ai", 4);
  const ally = makePlayer("aid-next-ally", 1, "dawn", "ai", 0);
  const guardian = makePlayer("aid-next-guardian", 2, "dawn", "human", 1);
