test("调律师：协调只看转移接收者：给敌人不触发，从敌人给队友才触发", async () => {
  const noTriggerTuner = makePlayer("no-trigger", 0, "dawn", "human", 7),
    allySource = makePlayer("ally-source", 1, "dawn"),
    enemyReceiver = makePlayer("enemy-receiver", 2, "dusk");
  const firstUse = instance("transfer"), firstMoved = instance("harvest");
  noTriggerTuner.hand.push(firstUse);
  allySource.hand.push(firstMoved);
  const { game: firstGame }
    = makeGame([noTriggerTuner, allySource, enemyReceiver]);
  registerPassiveSkills(firstGame);
  await firstGame.playCard(
    noTriggerTuner,
    firstUse,
    [],
    { sourceId: allySource.id, receiverId: enemyReceiver.id, zone: "hand" }
  );
  assert.equal(noTriggerTuner.turnFlags.coordinationTriggered, false);
  const enemyOnlyTuner = makePlayer("enemy-only", 0, "dawn", "ai", 7),
    enemySourceOnly = makePlayer("enemy-source-only", 1, "dusk"),
    enemyReceiverOnly = makePlayer("enemy-receiver-only", 2, "dusk");
  const enemyUse = instance("transfer"), enemyMoved = instance("harvest");
  enemyOnlyTuner.hand.push(enemyUse);
  enemySourceOnly.hand.push(enemyMoved);
  const { game: enemyGame }
    = makeGame([enemyOnlyTuner, enemySourceOnly, enemyReceiverOnly]);
  registerPassiveSkills(enemyGame);
  await enemyGame.playCard(
    enemyOnlyTuner,
    enemyUse,
    [],
    { sourceId: enemySourceOnly.id, receiverId: enemyReceiverOnly.id, zone: "hand" }
  );
  assert.equal(enemyOnlyTuner.turnFlags.coordinationTriggered, false);
  const triggerTuner = makePlayer("trigger", 0, "dawn", "ai", 7),
    enemySource = makePlayer("enemy-source", 1, "dusk"),
    allyReceiver = makePlayer("ally-receiver", 2, "dawn");
  const secondUse = instance("transfer"), secondMoved = instance("harvest");
  triggerTuner.hand.push(secondUse);
  enemySource.hand.push(secondMoved);
  const { game: secondGame }
    = makeGame([triggerTuner, enemySource, allyReceiver]);
  secondGame.state.deck.cards.push(instance("charge"));
  registerPassiveSkills(secondGame);
  await secondGame.playCard(
    triggerTuner, secondUse, [], { sourceId: enemySource.id, receiverId: allyReceiver.id, zone: "hand" }
  );
  assert.equal(triggerTuner.turnFlags.coordinationTriggered, true);
  assert.ok(allyReceiver.hand.includes(secondMoved));
});

