test("AI·突袭：模拟器识别破势叠加后强化普通突袭", () => {
  const visible = {
    players: [
      {
        id: "a",
        seatIndex: 0,
        battleTeam: "dawn",
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        maxEnergy: 4,
        attackRange: 1,
        attackUsed: 0,
        attackLimit: 2,
        recoverUsed: 0,
        recoverLimit: null,
        exposeWeaknessStacks: 0,
        alive: true,
        handCount: 3,
        hand: [
          { id: "x1", definitionId: "exposeWeakness" },
          { id: "x2", definitionId: "exposeWeakness" },
          { id: "a1", definitionId: "assault" }
        ]
      },
      {
        id: "b",
        seatIndex: 1,
        battleTeam: "dusk",
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        maxEnergy: 3,
        attackRange: 1,
        alive: true,
        handCount: 0
      }
    ]
  };
  const simulator = new AiSimulator(visible);
  const once = simulator.apply(
    visible, { type: "card", card: { id: "x1", definitionId: "exposeWeakness" }, targets: [] }, "a"
  );
  const twice = simulator.apply(
    once, { type: "card", card: { id: "x2", definitionId: "exposeWeakness" }, targets: [] }, "a"
  );
  const attacked = simulator.apply(
    twice, { type: "card", card: { id: "a1", definitionId: "assault" }, targets: [{ id: "b" }] }, "a"
  );
  assert.equal(attacked.players[1].hp, 1);
  assert.equal(attacked.players[0].exposeWeaknessStacks, 0);
  assert.equal(attacked.players[0].recoverLimit, null);
});

