test("AI·借势：根节点在无普通突袭敌人时仍生成同阵营借势意图", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    first = makePlayer("first", 1, "dawn"),
    ally = makePlayer("ally", 2, "dawn"),
    use = instance("leverage");
  actor.hand.push(use);
  first.equipment = instance("energyDevice");
  const { game }
    = makeGame([actor, first, ally]);
  assert.deepEqual(RuleEngine.getLegalAssaultTargets(game, first), []);
  const actions = game.aiController.actionGenerator.generate(
    actor
  ).filter((action) => action.card?.id === use.id);
  assert.ok(
    actions.some(
      (action) => action.selection.firstTargetId === first.id && action.selection.equipmentCardId === first.equipment.id && action.selection.secondTargetId === actor.id
    )
  );
});

test("AI·借势：深层生成在无普通突袭敌人时仍枚举同阵营借势第二目标", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    first = makePlayer("first", 1, "dawn"),
    ally = makePlayer("ally", 2, "dawn"),
    use = instance("leverage");
  actor.hand.push(use);
  first.equipment = instance("energyDevice");
  const { game }
    = makeGame([actor, first, ally]);
  const visible = createAiVisibleState(actor.id, game.state),
    visibleFirst = visible.players.find((player) => player.id === first.id);
  const simulationGame = { state: { players: visible.players } };
  assert.equal(RuleEngine.getLegalAssaultTargets(simulationGame, visibleFirst).length, 0);
  assert.ok(
    RuleEngine.getAssaultTargetCandidates(
      simulationGame, visibleFirst
    ).some((player) => player.id === actor.id)
  );
  const deepActions = game.aiController.actionGenerator.generateFromVisible(
    visible, actor.id
  ).filter((action) => action.card?.id === use.id);
  assert.ok(
    deepActions.some(
      (action) => action.selection.firstTargetId === first.id && action.selection.equipmentCardId === null && action.selection.equipmentDefinitionId === "energyDevice" && action.selection.secondTargetId === actor.id
    )
  );
});

test("AI·借势：在已用次数耗尽时仍能评估并接受残血击杀", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    first = makePlayer("first", 1, "dusk", "ai"),
    second = makePlayer("second", 2, "dawn", "ai"),
    equipment = instance("telescope"),
    assault = instance("assault");
  actor.hand.push(instance("leverage"));
  first.hand.push(assault);
  first.equipment = equipment;
  second.hp = 1;
  const { game }
    = makeGame([actor, first, second]);
  first.turnFlags.attackUsed = first.turnFlags.attackLimit;
  const usable = RuleEngine.getUsableAssaultCards(game, first, second);
  assert.equal(usable.length, 1);
  assert.equal(usable[0], assault);
  assert.equal(
    game.aiController.responsePolicy.shouldRespond(
      first, "leverageAssault", { target: second, equipment }, usable
    ),
    true
  );
});

test("AI·借势：主动借势第一目标需有距离合法第二目标且第二目标只按距离枚举", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    first = makePlayer("first", 1, "dusk"),
    ally = makePlayer("ally", 2, "dusk"),
    far = makePlayer("far", 3, "dawn"),
    tail = makePlayer("tail", 4, "dawn"),
    use = instance("leverage");
  actor.hand.push(use);
  first.equipment = instance("energyDevice");
  const { game }
    = makeGame([actor, first, ally, far, tail]);
  const actions = game.aiController.getLegalActions(
    actor
  ).filter((action) => action.card?.id === use.id);
  assert.ok(actions.length > 0);
  for (const action of actions) {
    assert.equal(action.selection.firstTargetId, first.id);
    assert.equal(action.selection.equipmentCardId, first.equipment.id);
    assert.ok(RuleEngine.getAssaultTargetCandidates(game, first).includes(action.targets[1]));
  }
  assert.ok(actions.some((action) => action.targets[1] === actor));
  assert.ok(actions.some((action) => action.targets[1] === ally));
  assert.ok(!actions.some((action) => action.targets[1] === far));
  assert.ok(!actions.some((action) => action.targets[1] === tail));
});

test("AI·借势：不会因估计没有突袭或次数用尽删除合法借势组合", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    first = makePlayer("first", 1, "dusk"),
    use = instance("leverage");
  actor.hand.push(use);
  first.equipment = instance("energyDevice");
  const { game }
    = makeGame([actor, first]);
  first.turnFlags.attackUsed = first.turnFlags.attackLimit;
  const rootActions = game.aiController.getLegalActions(
    actor
  ).filter((action) => action.card?.id === use.id);
  assert.ok(rootActions.length > 0);
  const visible = createAiVisibleState(actor.id, game.state),
    visibleFirst = visible.players.find((player) => player.id === first.id);
  assert.equal(visibleFirst.assaultResponseProbability, 0);
  assert.equal(visibleFirst.attackUsed, visibleFirst.attackLimit);
  const deepActions = game.aiController.actionGenerator.generateFromVisible(
    visible, actor.id
  ).filter((action) => action.card?.id === use.id);
  assert.ok(deepActions.length > 0);
  assert.ok(deepActions.some((action) => action.selection.secondTargetId === actor.id));
});

