test("AI·雷达：战术判定免疫且不消耗原格挡，基础与装备判定按真实顺序结算", () => {
  const simulator = new AiSimulator({ players: [] });
  const run = ({ handCount, blockProbability, judgment }) => {
    const state = {
      players: [
        { id: "attacker", battleTeam: "dawn", alive: true, hp: 4, maxHp: 4, handCount: 0 },
        {
          id: "target",
          battleTeam: "dusk",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          handCount,
          blockProbability,
          twoBlockProbability: 0,
          equipmentDefinitionId: "defenseDevice",
          equipmentRetentionProbability: 1,
          expectedRecoverCount: 0
        }
      ]
    };
    simulator.applyDamage(
      state,
      state.players[0],
      state.players[1],
      1,
      { canBlock: true, deviceAttack: true, radarJudgmentProbabilities: judgment }
    );
    return state.players[1];
  };
  const tactic = run(
    { handCount: 1, blockProbability: 1, judgment: { block: 0, otherBasic: 0, equipment: 0 } }
  );
  assert.equal(tactic.hp, 4);
  assert.equal(tactic.handCount, 1);
  const judgedBlock = run(
    { handCount: 0, blockProbability: 0, judgment: { block: 1, otherBasic: 0, equipment: 0 } }
  );
  assert.equal(judgedBlock.hp, 4);
  assert.equal(judgedBlock.handCount, 0);
  const otherBasic = run(
    { handCount: 0, blockProbability: 0, judgment: { block: 0, otherBasic: 1, equipment: 0 } }
  );
  assert.equal(otherBasic.hp, 3);
  assert.equal(otherBasic.handCount, 1);
  const equipment = run(
    { handCount: 1, blockProbability: 1, judgment: { block: 0, otherBasic: 0, equipment: 1 } }
  );
  assert.equal(equipment.hp, 4);
  assert.equal(equipment.handCount, 0);
});

