test("AI·望远镜与屏障：望远镜与目标屏障组合分支各计一次且不重复质量", () => {
  const source = {
    id: "source",
    seatIndex: 0,
    battleTeam: "dawn",
    alive: true,
    equipmentDefinitionId: "telescope",
    equipmentRetentionProbability: .4
  };
  const target = {
    id: "target",
    seatIndex: 2,
    battleTeam: "dusk",
    alive: true,
    equipmentDefinitionId: "barrierDevice",
    equipmentRetentionProbability: .25
  };
  const game = {
    state: {
      players: [
        source,
        { id: "middle", seatIndex: 1, alive: true },
        target,
        { id: "tail", seatIndex: 3, alive: true }
      ]
    }
  };
  const branches = DistanceSystem.getRangeConditionBranches(game, { source, target, range: 1 });
  assert.equal(branches.length, 4);
  assertClose(branches.reduce((sum, branch) => sum + branch.probability, 0), 1);
  assert.equal(new Set(branches.map((branch) => JSON.stringify(branch.conditions))).size, 4);
  assertClose(
    branches.filter((branch) => branch.matches).reduce((sum, branch) => sum + branch.probability, 0), .3
  );
});

