test("AI·刃行者：概率破军只在发动世界新增可用突袭次数槽", () => {
  const shared = "break-army-energy",
    state = {
      playPhaseEnded: false,
      players: [
        {
          id: "blade",
          seatIndex: 0,
          battleTeam: "dawn",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: .8,
          maxEnergy: 4,
          energyBranches: [
            { probability: .4, conditions: { [shared]: "yes" }, amount: 2 },
            { probability: .6, conditions: { [shared]: "no" }, amount: 0 }
          ],
          handCount: 1,
          hand: [{ id: "hit", definitionId: "assault" }],
          attackUsed: 1,
          attackLimit: 1,
          attackRange: 1,
          activeSkillId: "breakArmy",
          activeSkillUses: 0,
          activeSkillLimit: 1
        },
        {
          id: "enemy",
          seatIndex: 1,
          battleTeam: "dusk",
          alive: true,
          hp: 5,
          maxHp: 5,
          shield: 0,
          handCount: 0,
          blockProbability: 0,
          twoBlockProbability: 0,
          expectedRecoverCount: 0
        }
      ]
    },
    { game }
      = makeGame([makePlayer("real-a", 0, "dawn"), makePlayer("real-b", 1, "dusk")]);
  const skill = game.aiController.actionGenerator.generateFromVisible(
    state, "blade"
  ).find((action) => action.skill?.id === "breakArmy");
  assertClose(skill.executionProbability, .4);
  const boosted = new AiSimulator(state).apply(state, skill, "blade");
  assertClose(boosted.players[0].attackLimit, 1.4);
  const assault = game.aiController.actionGenerator.generateFromVisible(
    boosted, "blade"
  ).find((action) => action.card?.id === "hit");
  assertClose(assault.executionProbability, .4);
});

test("AI·刃行者：破军只在额外攻击槽确实有第二张突袭可用时生成", () => {
  const blade = makePlayer("break-army-blade", 0, "dawn", "ai", 0),
    enemy = makePlayer("break-army-enemy", 1, "dusk");
  blade.energy = 2;
  blade.hand.push(instance("assault"));
  const { game }
    = makeGame([blade, enemy]);
  blade.energy = 2;
  const skills = () => game.aiController.getLegalActions(
    blade
  ).filter((action) => action.skill?.id === "breakArmy");
  assert.equal(skills().length, 0);
  assert.equal(
    game.aiController.evaluator.breakArmyUtility(createAiVisibleState(blade.id, game.state).players[0]),
    -4
  );
  blade.turnFlags.attackUsed = blade.turnFlags.attackLimit;
  assert.equal(skills().length, 1);
  assert.equal(
    game.aiController.evaluator.breakArmyUtility(createAiVisibleState(blade.id, game.state).players[0]),
    8
  );
});

