test("AI·守誓者：护援统一覆盖突袭、震荡、挑衅、决斗、猎杀与焚场", () => {
  const runCard = (definitionId, targetSetup = () => { }) => {
    const actor = {
      id: `${definitionId}-actor`,
      seatIndex: 0,
      battleTeam: "dawn",
      alive: true,
      hp: 5,
      maxHp: 5,
      shield: 0,
      energy: 3,
      maxEnergy: 4,
      handCount: 1,
      hand: [{ id: `${definitionId}-card`, definitionId }],
      attackUsed: 0,
      attackLimit: 2,
      assaultCountDistribution: [{ count: definitionId === "assault" ? 1 : 0, probability: 1 }]
    };
    const target = {
      id: `${definitionId}-target`,
      seatIndex: 1,
      battleTeam: "dusk",
      alive: true,
      hp: 5,
      maxHp: 5,
      shield: 0,
      handCount: 0,
      blockProbability: 0,
      expectedRecoverCount: 0,
      assaultCountDistribution: [{ count: 0, probability: 1 }]
    };
    const guardian = {
      id: `${definitionId}-guardian`,
      seatIndex: 2,
      generalId: "oath-warden",
      battleTeam: "dusk",
      alive: true,
      hp: 3,
      maxHp: 3,
      shield: 0,
      handCount: 1,
      hand: [{ id: `${definitionId}-aid`, definitionId: "charge" }],
      guardianAidUsedProbability: 0
    };
    targetSetup(actor, target);
    const state = { players: [actor, target, guardian] },
      next = new AiSimulator(
        state
      ).apply(state, { type: "card", card: { ...CARD_DEFINITIONS[definitionId], id: `${definitionId}-card` }, targets: [target] }, actor.id);
    assert.equal(next.players[1].hp, 5);
    assert.equal(next.players[2].handCount, 0);
  };
  for (const id of ["assault", "shockwave", "provoke", "duel"]) runCard(id);
  const runSkill = (skill, actorGeneral, damage) => {
    const actor = {
      id: `${skill.id}-actor`,
      seatIndex: 0,
      generalId: actorGeneral,
      battleTeam: "dawn",
      alive: true,
      hp: 5,
      maxHp: 5,
      shield: 0,
      energy: 3,
      maxEnergy: 4,
      handCount: 0,
      activeSkillUses: 0
    };
    const target = {
      id: `${skill.id}-target`,
      seatIndex: 1,
      battleTeam: "dusk",
      alive: true,
      hp: 5,
      maxHp: 5,
      shield: 0,
      handCount: 0,
      blockProbability: 0,
      expectedRecoverCount: 0,
      statuses: [],
      huntMarkSourceId: actor.id,
      huntMarkProbability: 1,
      huntMarkProbabilities: { [actor.id]: 1 },
      huntMarkStateBranchesBySource: { [actor.id]: [{ probability: 1, conditions: {}, marked: true }] }
    };
    const guardian = {
      id: `${skill.id}-guardian`,
      seatIndex: 2,
      generalId: "oath-warden",
      battleTeam: "dusk",
      alive: true,
      hp: 3,
      maxHp: 3,
      shield: 0,
      handCount: 1,
      hand: [{ id: `${skill.id}-aid`, definitionId: "charge" }],
      guardianAidUsedProbability: 0
    };
    const state = { players: [actor, target, guardian] },
      next = new AiSimulator(state).apply(state, { type: "skill", skill, targets: [target] }, actor.id);
    assert.equal(next.players[1].hp, 5 - (damage - 1));
    assert.equal(next.players[2].handCount, 0);
  };
  runSkill(ACTIVE_SKILLS.hunt, "trail-hunter", 2);
  runSkill(ACTIVE_SKILLS.burningField, "ember-magus", 1);
});

test("AI·守誓者：护援在单个模拟快照内只触发一次且零伤害与阵亡时不弃牌", () => {
  const attacker = {
    id: "aid-attacker", battleTeam: "dawn", alive: true, hp: 5, maxHp: 5, handCount: 0
  };
  const target = {
    id: "aid-target",
    battleTeam: "dusk",
    alive: true,
    hp: 5,
    maxHp: 5,
    shield: 0,
    handCount: 0,
    blockProbability: 0,
    expectedRecoverCount: 0
  };
  const guardian = {
    id: "aid-guardian",
    generalId: "oath-warden",
    battleTeam: "dusk",
    alive: true,
    hp: 3,
    maxHp: 3,
    handCount: 2,
    guardianAidUsedProbability: 0
  };
  const state = { players: [attacker, target, guardian] }, simulator = new AiSimulator(state);
  simulator.applyDamage(state, attacker, target, 0, { canBlock: false });
  assert.equal(guardian.handCount, 2);
  simulator.applyDamage(state, attacker, target, 1, { canBlock: false });
  simulator.applyDamage(state, attacker, target, 1, { canBlock: false });
  assert.equal(guardian.handCount, 1);
  assert.equal(target.hp, 4);
  const dead = {
    ...guardian, id: "dead-aid", alive: false, handCount: 1, guardianAidUsedProbability: 0
  },
    deadTarget = { ...target, id: "dead-aid-target", hp: 5 };
  const deadState = { players: [attacker, deadTarget, dead] };
  simulator.applyDamage(deadState, attacker, deadTarget, 1, { canBlock: false });
  assert.equal(dead.handCount, 1);
  assert.equal(deadTarget.hp, 4);
});

