test("AI·调律师：协调只依据未取消的其他己方有效目标且同回合一次", () => {
  const actor = {
    id: "coord-sim",
    seatIndex: 0,
    generalId: "resonance-tuner",
    battleTeam: "dawn",
    alive: true,
    hp: 4,
    maxHp: 4,
    shield: 0,
    handCount: 2,
    hand: [{ id: "coord-one", definitionId: "shield" }, { id: "coord-two", definitionId: "shield" }],
    coordinationTriggered: false
  };
  const ally = {
    id: "coord-ally",
    seatIndex: 1,
    battleTeam: "dawn",
    alive: true,
    hp: 4,
    maxHp: 4,
    shield: 0,
    handCount: 0
  };
  const enemy = {
    id: "coord-enemy",
    seatIndex: 2,
    battleTeam: "dusk",
    alive: true,
    hp: 4,
    maxHp: 4,
    shield: 0,
    handCount: 0,
    counterProbability: 0
  };
  const state = { players: [actor, ally, enemy] },
    simulator = new AiSimulator(state),
    action = (id, target) => (
      { type: "card", card: { ...CARD_DEFINITIONS.shield, id }, targets: [target] }
    );
  const once = simulator.apply(state, action("coord-one", ally), actor.id);
  assert.equal(once.players[0].handCount, 2);
  assert.equal(once.players[0].coordinationTriggered, true);
  const twice = simulator.apply(once, action("coord-two", ally), actor.id);
  assert.equal(twice.players[0].handCount, 1);
  const selfState = structuredClone(state),
    selfOnly = new AiSimulator(
      selfState
    ).apply(selfState, action("coord-one", selfState.players[0]), actor.id);
  assert.equal(selfOnly.players[0].coordinationTriggered, false);
  const counterActor = {
    ...actor,
    id: "coord-countered",
    handCount: 1,
    hand: [{ id: "coord-mutual", definitionId: "mutualBenefit" }],
    coordinationTriggered: false
  },
    counterAlly = { ...ally, id: "coord-counter-ally" },
    counterEnemy = { ...enemy, id: "coord-counter-enemy", counterProbability: 1 };
  const counterState = { players: [counterActor, counterAlly, counterEnemy] };
  const countered = new AiSimulator(
    counterState
  ).apply(counterState, { type: "card", card: { ...CARD_DEFINITIONS.mutualBenefit, id: "coord-mutual" }, targets: counterState.players }, counterActor.id);
  assert.equal(countered.players[0].coordinationTriggered, false);
});

