  const state = { players: [counterPlayer("a", "dawn"), source, receiver] };
  const simulator = new AiSimulator({ players: [] });
  simulator.transferKnownCardIdentity(
    state,
    source,
    receiver,
    { cardId: "c1", definitionId: "counter" },
    [{ probability: 1, conditions: {}, occurs: true }],
    false
  );
