test("AI·格挡概率：概率伤害先逐世界结算护盾再汇总期望", () => {
  const run = ({ amount, eventProbability, shield, blockProbability = 0 }) => {
    const state = {
      players: [
        { id: "attacker", battleTeam: "dawn", alive: true, hp: 4, maxHp: 4, handCount: 0 },
        {
          id: "target",
          battleTeam: "dusk",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield,
          handCount: blockProbability ? 1 : 0,
          blockProbability,
          twoBlockProbability: 0,
          expectedRecoverCount: 0
        }
      ]
    };
    const simulator = new AiSimulator(state),
      outcome = {},
      damage = simulator.applyDamage(
        state,
        state.players[0],
        state.players[1],
        amount,
        { canBlock: blockProbability > 0, eventProbability, outcome }
      );
    return { state, target: state.players[1], damage, outcome };
  };
  let result = run({ amount: 2, eventProbability: .4, shield: 1 });
  assertClose(result.target.shield, .6);
  assertClose(result.target.hp, 3.6);
  assertClose(result.damage, .4);
  assertClose(result.outcome.lifeDamageChance, .4);
  result = run({ amount: 1, eventProbability: .4, shield: 1 });
  assertClose(result.target.shield, .6);
  assertClose(result.target.hp, 4);
  result = run({ amount: 2, eventProbability: .4, shield: 2 });
  assertClose(result.target.shield, 1.2);
  assertClose(result.target.hp, 4);
  result = run({ amount: 2, eventProbability: .4, shield: 1, blockProbability: .5 });
  assertClose(result.target.shield, .8);
  assertClose(result.target.hp, 3.8);
  assertClose(result.target.handCount, .8);
  assertClose(result.outcome.lifeDamageChance, .2);
  result = run({ amount: 3, eventProbability: 1, shield: 2 });
  assertClose(result.target.shield, 0);
  assertClose(result.target.hp, 3);
  assertClose(result.outcome.lifeDamageChance, 1);
});

