test("AI·救援：强制救援：重新征召会取消尚未完成的 AI 救援等待", async () => {
  const human = makePlayer("human", 0, "dawn", "human"),
    ally = makePlayer("ally", 1, "dawn"),
    enemy = makePlayer("enemy", 2, "dusk");
  human.hp = 0;
  const card = instance("recover");
  ally.hand.push(card);
  const { game, ui }
    = makeGame([human, ally, enemy]);
  game.simulationMode = false;
  game.cleanupManager = new CleanupManager();
  const pending = game.responseSystem.requestDyingRescue(ally, human, card);
  game.dispose();
  const result = await pending;
  assert.equal(result.status, "cancelled");
  assert.equal(result.card, null);
  assert.ok(ally.hand.includes(card));
  assert.equal(game.cleanupManager.pending.size, 0);
  assert.equal(game.state.pendingResponses.length, 0);
  assert.equal(ui.thinking.at(-1)[0], false);
});

test("AI·救援：强制救援：救援经过 Game.heal 并产生治疗事件与统计", async () => {
  const human = makePlayer("human", 0, "dawn", "human"),
    ally = makePlayer("ally", 1, "dawn"),
    enemy = makePlayer("enemy", 2, "dusk");
  human.hp = 0;
  ally.hand.push(instance("recover"));
  const { game }
    = makeGame([human, ally, enemy]);
  const events = [];
  game.eventBus.on(
    "beforeHeal",
    "test:forced-before",
    (event) => events.push([event.type, event.isDyingRescue, event.reason])
  );
  game.eventBus.on(
    "afterHeal", "test:forced-after", (event) => events.push([event.type, event.actualAmount])
  );
  await game.dyingSystem.enter(human, enemy);
  assert.deepEqual(events, [["beforeHeal", true, "dyingRescue"], ["afterHeal", 1]]);
  assert.equal(ally.statistics.healingDone, 1);
  assert.equal(human.hp, 1);
});

test("AI·救援：自救响应策略为确定必用，敌方救援为拒绝", () => {
  const a = makePlayer("a", 0, "dawn"),
    ally = makePlayer("ally", 1, "dawn"),
    enemy = makePlayer("enemy", 2, "dusk");
  const { game }
    = makeGame([a, ally, enemy]);
  assert.equal(
    game.aiController.responsePolicy.shouldRespond(
      a, "dyingRescue", { target: a }, [instance("recover")]
    ),
    true
  );
  assert.equal(
    game.aiController.responsePolicy.shouldRespond(
      enemy, "dyingRescue", { target: a }, [instance("recover")]
    ),
    false
  );
});

