const makeRemainingKnowledge = (viewer, state = null) => {
  const game = {
    state: state ?? {
      deck: { discardPile: [], resolvingCards: [], judgmentZone: [] }, players: [], publicCardPool: []
    },
    random: () => 0
  };
  return new AiKnowledge(game);
};

