test("AI·角色核心评分：换装、丢失与概率获得装备按角色差量计算", () => {
  const { game }
    = makeGame([makePlayer("viewer", 0, "dawn")]);
  const evaluator = game.aiController.evaluator;
  const enemy = {
    id: "enemy", battleTeam: "dusk", alive: true, hp: 4, maxHp: 4, shield: 0, energy: 0, handCount: 0
  };
  const base = {
    id: "viewer",
    battleTeam: "dawn",
    generalId: "blade-walker",
    alive: true,
    hp: 4,
    maxHp: 4,
    shield: 0,
    energy: 0,
    handCount: 0,
    initialEquipmentRoleDelta: 2
  };
  // 换装到 energyDevice：blade-walker 差量 -1，初始 battleDevice 差量 +2 → 净差量 -3
  const swapped = evaluator.stateUtility(
    {
      players: [
        {
          ...base,
          equipmentDefinitionId: "energyDevice",
          equipmentRetentionProbability: 1,
          expectedEquipmentRoleDelta: 0
        },
        enemy
      ]
    },
    "viewer"
  );
  const swappedNoBaseline = evaluator.stateUtility(
    {
      players: [
        {
          ...base,
          initialEquipmentRoleDelta: 0,
          equipmentDefinitionId: "energyDevice",
          equipmentRetentionProbability: 1,
          expectedEquipmentRoleDelta: 0
        },
        enemy
      ]
    },
    "viewer"
  );
  assertClose(swappedNoBaseline - swapped, .5);
  // 装备丢失：当前保留概率 0，初始差量 2 相对初始差量 0 的角色装备差量为 -2
  const lostWithBaseline = evaluator.stateUtility(
    {
      players: [
        {
          ...base,
          equipmentDefinitionId: "battleDevice",
          equipmentRetentionProbability: 0,
          expectedEquipmentRoleDelta: 0
        },
        enemy
      ]
    },
    "viewer"
  );
  const lostNoBaseline = evaluator.stateUtility(
    {
      players: [
        {
          ...base,
          initialEquipmentRoleDelta: 0,
          equipmentDefinitionId: "battleDevice",
          equipmentRetentionProbability: 0,
          expectedEquipmentRoleDelta: 0
        },
        enemy
      ]
    },
    "viewer"
  );
  assertClose(lostNoBaseline - lostWithBaseline, .5);
  // 概率获得已知装备：expectedEquipmentRoleDelta 按接收者角色差量 × 概率
  const gained = evaluator.stateUtility(
    {
      players: [
        {
          ...base,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          initialEquipmentRoleDelta: 0,
          expectedEquipmentRoleDelta: 1
        },
        enemy
      ]
    },
    "viewer"
  );
  const noGain = evaluator.stateUtility(
    {
      players: [
        {
          ...base,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          initialEquipmentRoleDelta: 0,
          expectedEquipmentRoleDelta: 0
        },
        enemy
      ]
    },
    "viewer"
  );
  assertClose(gained - noGain, .25);
});

test("AI·角色核心评分：借势概率获得装备同步接收者角色装备差量", () => {
  const state = {
    players: [
      {
        id: "actor",
        seatIndex: 0,
        battleTeam: "dawn",
        generalId: "blade-walker",
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        alive: true,
        handCount: 1,
        hand: [{ id: "l", definitionId: "leverage" }],
        counterProbability: 0,
        expectedEquipmentGain: 0,
        expectedEquipmentRoleDelta: 0
      },
      {
        id: "first",
        seatIndex: 1,
        battleTeam: "dusk",
        generalId: "oath-warden",
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        alive: true,
        handCount: 2,
        attackUsed: 0,
        attackLimit: 1,
        equipmentDefinitionId: "battleDevice",
        equipmentRetentionProbability: 1,
        assaultResponseProbability: .5,
        expectedAssaultCount: .5,
        blockProbability: 0,
        counterProbability: 0
      },
      {
        id: "second",
        seatIndex: 2,
        battleTeam: "dawn",
        hp: 4,
        maxHp: 4,
        shield: 0,
        energy: 0,
        alive: true,
        handCount: 0,
        blockProbability: 0,
        expectedRecoverCount: 0
      }
    ]
  };
  const simulator = new AiSimulator(state);
  const next = simulator.apply(
    state,
    {
      type: "card",
      card: { ...CARD_DEFINITIONS.leverage, id: "l" },
      targets: [{ id: "first" }, { id: "second" }],
      selection: { firstTargetId: "first", secondTargetId: "second" }
    },
    "actor"
  );
  const actor = next.players[0], first = next.players[1];
  const declineProbability = 1 - first.equipmentRetentionProbability;
  const bladeBattleDeviceDelta = getRoleCardAiValue(
    "blade-walker", "battleDevice"
  ) - getBaseCardAiValue("battleDevice");
  assert.ok(declineProbability > 0 && declineProbability < 1);
  assertClose(actor.expectedEquipmentRoleDelta, bladeBattleDeviceDelta * declineProbability);
  assert.ok(actor.expectedEquipmentGain > 0);
});

test("AI·角色核心评分：真实 Planner 会按角色权重选择不同动作", async () => {
  const run = async (generalIndex) => {
    const actor = makePlayer("actor", 0, "dawn", "ai", generalIndex);
    const enemy = makePlayer("enemy", 1, "dusk");
    const provoke = instance("provoke"), harvest = instance("harvest");
    actor.hand = [provoke, harvest];
    enemy.hand = [instance("assault")];
    const { game }
      = makeGame([actor, enemy]);
    game.rememberPrivateCard(actor, enemy, enemy.hand[0]);
    game.aiSearchNodeBudgetOverride = 3;
    game.aiRandomnessRange = 0;
    const action = await game.aiController.selectAction(actor, { gameId: game.state.gameId });
    return action.card?.definitionId;
  };
  // 全局基础值相同（provoke/harvest 均为 8），角色差量：刃行者 +1/0，灵医 -1/+1
  assert.equal(CARD_DEFINITIONS.provoke.aiValue, CARD_DEFINITIONS.harvest.aiValue);
  assert.equal(await run(0), "provoke");
  assert.equal(await run(2), "harvest");
});

