test("AI·转移评分：转移角色权重：相同突袭不同来源角色的来源损失精确反映角色差值", () => {
  const actor = { id: "actor", battleTeam: "dawn" };
  const receiver = { id: "receiver", battleTeam: "dawn", generalId: "spirit-medic", hp: 3, maxHp: 3 };
  const makeFrom = (generalId) => (
    {
      id: "from",
      battleTeam: "dusk",
      generalId,
      hp: 3,
      maxHp: 3,
      handCount: 1,
      knownCards: [{ cardId: "k", definitionId: "assault" }]
    }
  );
  const blade = chooseTransferHandCandidate(actor, makeFrom("blade-walker"), receiver);
  const warden = chooseTransferHandCandidate(actor, makeFrom("oath-warden"), receiver);
  assert.equal(blade.selectionKind, "known");
  assert.equal(blade.expectedValue, getRoleCardAiValue("spirit-medic", "assault"));
  assert.equal(
    blade.utility,
    getRoleCardAiValue("blade-walker", "assault") + getRoleCardAiValue("spirit-medic", "assault")
  );
  assert.equal(
    warden.utility,
    getRoleCardAiValue("oath-warden", "assault") + getRoleCardAiValue("spirit-medic", "assault")
  );
  assert.equal(blade.utility - warden.utility, 3);
});

test("AI·转移评分：转移角色权重：已知牌接收者角色价值进入效用与 expectedValue", () => {
  const actor = { id: "actor", battleTeam: "dawn" };
  const source = {
    id: "source",
    battleTeam: "dusk",
    generalId: "blade-walker",
    hp: 3,
    maxHp: 3,
    handCount: 1,
    knownCards: [{ cardId: "k", definitionId: "counter" }]
  };
  const bladeReceiver = { id: "r1", battleTeam: "dawn", generalId: "blade-walker", hp: 4, maxHp: 4 };
  const medicReceiver = { id: "r2", battleTeam: "dawn", generalId: "spirit-medic", hp: 3, maxHp: 3 };
  const bladeCandidate = chooseTransferHandCandidate(actor, source, bladeReceiver);
  const medicCandidate = chooseTransferHandCandidate(actor, source, medicReceiver);
  const bladeValue = getRoleCardAiValue("blade-walker", "counter"),
    medicValue = getRoleCardAiValue("spirit-medic", "counter");
  assert.equal(bladeCandidate.expectedValue, bladeValue);
  assert.equal(medicCandidate.expectedValue, medicValue);
  assert.equal(bladeCandidate.utility, bladeValue + bladeValue);
  assert.equal(medicCandidate.utility, bladeValue + medicValue);
  assert.equal(bladeValue, 8);
  assert.equal(medicValue, 9);
  assert.ok(medicCandidate.utility > bladeCandidate.utility);
});

test("AI·转移评分：转移角色权重：恢复牌同时叠加角色基础价值与生命情境修正", () => {
  const full = { generalId: "spirit-medic", hp: 3, maxHp: 3 };
  const low = { generalId: "spirit-medic", hp: 1, maxHp: 3 };
  const bladeFull = { generalId: "blade-walker", hp: 4, maxHp: 4 };
  assert.equal(
    cardSituationValue("recover", full), getRoleCardAiValue("spirit-medic", "recover") - 2
  );
  assert.equal(
    cardSituationValue("recover", low), getRoleCardAiValue("spirit-medic", "recover") + 7 + 2
  );
  assert.equal(
    cardSituationValue("recover", bladeFull), getRoleCardAiValue("blade-walker", "recover") - 2
  );
  assert.equal(cardSituationValue("recover", full) - cardSituationValue("recover", bladeFull), 2);
});

test("AI·转移评分：转移角色权重：未知牌动态期望随角色与剩余分布变化", () => {
  const actor = { id: "actor", battleTeam: "dawn" };
  const makeSource = (generalId) => (
    { id: "from", battleTeam: "dusk", generalId, hp: 4, maxHp: 4, handCount: 1, knownCards: [] }
  );
  const makeReceiver = (generalId) => (
    { id: "receiver", battleTeam: "dawn", generalId, hp: 3, maxHp: 3, handCount: 0 }
  );
  const assaultCounts = { assault: 10 }, recoverCounts = { recover: 10 };
  const assaultCandidate = chooseTransferHandCandidate(
    actor, makeSource("blade-walker"), makeReceiver("spirit-medic"), null, assaultCounts
  );
  const recoverCandidate = chooseTransferHandCandidate(
    actor, makeSource("blade-walker"), makeReceiver("spirit-medic"), null, recoverCounts
  );
  assert.equal(assaultCandidate.selectionKind, "unknown");
  assert.equal(assaultCandidate.expectedValue, getRoleCardAiValue("spirit-medic", "assault"));
  assert.equal(
    assaultCandidate.utility,
    getRoleCardAiValue("blade-walker", "assault") + getRoleCardAiValue("spirit-medic", "assault")
  );
  assert.equal(recoverCandidate.expectedValue, getRoleCardAiValue("spirit-medic", "recover") - 2);
  assert.equal(
    recoverCandidate.utility,
    getRoleCardAiValue(
      "blade-walker", "recover"
    ) - 2 + getRoleCardAiValue("spirit-medic", "recover") - 2
  );
  const wardenSource = chooseTransferHandCandidate(
    actor, makeSource("oath-warden"), makeReceiver("spirit-medic"), null, assaultCounts
  );
  assert.equal(
    wardenSource.utility,
    getRoleCardAiValue("oath-warden", "assault") + getRoleCardAiValue("spirit-medic", "assault")
  );
  assert.equal(assaultCandidate.utility - wardenSource.utility, 3);
  const bladeReceiver = chooseTransferHandCandidate(
    actor, makeSource("blade-walker"), makeReceiver("blade-walker"), null, assaultCounts
  );
  assert.equal(bladeReceiver.expectedValue, getRoleCardAiValue("blade-walker", "assault"));
  assert.equal(assaultCandidate.expectedValue - bladeReceiver.expectedValue, -3);
  assert.throws(
    () => chooseTransferHandCandidate(
      actor, makeSource("blade-walker"), makeReceiver("spirit-medic"), null, { "not-a-card": 1 }
    ),
    /未知卡牌 ID/
  );
});

