test("AI·转移评分：转移角色权重：根节点规划与实际选牌使用同一剩余计数选择相同候选", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    from = makePlayer("from", 1, "dusk"),
    receiver = makePlayer("receiver", 2, "dawn");
  const use = instance("transfer"), known = instance("assault"), unknown = instance("counter");
  actor.hand.push(use);
  from.hand = [known, unknown];
  const { game }
    = makeGame([actor, from, receiver], { random: () => 0 });
  game.rememberPrivateCard(actor, from, known);
  const counts = { recover: 10 };
  game.aiController.knowledge.remainingCounts = () => ({ ...counts });
  const plan = game.aiController.cardSelector.chooseTransferCombination(
    actor, CARD_DEFINITIONS.transfer, [from]
  );
  assert.ok(plan);
  const candidate = chooseTransferHandCandidate(actor, from, receiver, null, counts);
  assert.equal(candidate.selectionKind, "unknown");
  assert.equal(
    plan.score,
    scoreTransferCombination({ actor, from, receiver, zone: "hand", remainingCardCounts: counts })
  );
  const chosen = game.aiController.cardSelector.chooseHiddenCards(
    actor, from, 1, null, { purpose: "transfer", receiver }
  )[0];
  assert.equal(chosen, unknown);
});

test("AI·转移评分：转移角色权重：深层规划使用可见快照剩余计数", () => {
  const makeState = (counts) => (
    {
      playPhaseEnded: false,
      remainingCardCounts: counts,
      players: [
        {
          id: "a",
          seatIndex: 0,
          battleTeam: "dawn",
          generalId: "blade-walker",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 1,
          hand: [{ id: "use", definitionId: "transfer" }],
          attackRange: 1,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          counterProbability: 0
        },
        {
          id: "f",
          seatIndex: 1,
          battleTeam: "dusk",
          generalId: "oath-warden",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 1,
          knownCards: [],
          attackRange: 1,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          counterProbability: 0
        },
        {
          id: "r",
          seatIndex: 2,
          battleTeam: "dawn",
          generalId: "spirit-medic",
          alive: true,
          hp: 3,
          maxHp: 3,
          shield: 0,
          energy: 0,
          handCount: 0,
          attackRange: 1,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          counterProbability: 0
        }
      ]
    }
  );
  const actor = makePlayer("real", 0, "dawn"), enemy = makePlayer("other", 1, "dusk");
  const { game }
    = makeGame([actor, enemy]);
  const generator = game.aiController.actionGenerator;
  const assaultState = makeState({ assault: 10 }), recoverState = makeState({ recover: 10 });
  const assaultAction = generator.generateFromVisible(
    assaultState, "a"
  ).find((entry) => entry.card?.definitionId === "transfer");
  const recoverAction = generator.generateFromVisible(
    recoverState, "a"
  ).find((entry) => entry.card?.definitionId === "transfer");
  assert.ok(assaultAction);
  assert.ok(recoverAction);
  assert.notEqual(assaultAction.selection.receiverId, recoverAction.selection.receiverId);
  assert.notEqual(assaultAction.selection.score, recoverAction.selection.score);
  const assaultCandidate = chooseTransferHandCandidate(
    assaultState.players[0],
    assaultState.players[1],
    assaultState.players[2],
    null,
    assaultState.remainingCardCounts
  );
  const recoverCandidate = chooseTransferHandCandidate(
    recoverState.players[0],
    recoverState.players[1],
    recoverState.players[2],
    null,
    recoverState.remainingCardCounts
  );
  assert.equal(assaultCandidate.selectionKind, "unknown");
  assert.equal(assaultCandidate.expectedValue, getRoleCardAiValue("spirit-medic", "assault"));
  assert.equal(recoverCandidate.selectionKind, "unknown");
  assert.equal(recoverCandidate.expectedValue, getRoleCardAiValue("spirit-medic", "recover") - 2);
});

