test("UI·手牌：对局中缩放进入窄屏断点会自动折叠日志避免遮挡战场", () => {
  const previousWindow = globalThis.window;
  let collapsed = null;
  globalThis.window = { innerWidth: 1000 };
  const fake = {
    viewportWasNarrow: false,
    elements: { game_screen: { classList: { contains: () => false } } },
    setLogCollapsed: (value) => { collapsed = value; }
  };
  try {
    UIManager.prototype.handleViewportResize.call(fake);
    assert.equal(collapsed, true);
    assert.equal(fake.viewportWasNarrow, true);
    globalThis.window.innerWidth = 1440;
    UIManager.prototype.handleViewportResize.call(fake);
    assert.equal(collapsed, true);
    assert.equal(fake.viewportWasNarrow, false);
  } finally {
    if (previousWindow === undefined) delete globalThis.window; else globalThis.window = previousWindow;
  }
});

