for (const definitionId of ["duel", "provoke"]) test(`生命周期：旧局${CARD_DEFINITIONS[definitionId].name}响应取消后不会继续造成伤害`, async () => {
  const ui = makeOwnedUi(),
    source = makePlayer(`old-${definitionId}-source`, 0, "dawn"),
    target = makePlayer(`old-${definitionId}-target`, 1, "dusk", "human");
  const old = configureOwnedGame(new Game(ui), [source, target]);
  ui.attachGame(old);
  const use = instance(definitionId);
  source.hand.push(use);
  let openedResolve;
  const opened = new Promise((resolve) => {
    openedResolve = resolve;
  });
  ui.onResponse = (request) => {
    if (request.type === "counter") {
      const state = ui.responseState;
      ui.responseState = null;
      state.resolve({ status: "declined" });
    } else openedResolve();
  };
  const hp = target.hp, pending = old.playCard(source, use, [target]);
  await opened;
  old.dispose();
  const fresh = configureOwnedGame(
    new Game(ui),
    [
      makePlayer(`new-${definitionId}-human`, 0, "dawn", "human"),
      makePlayer(`new-${definitionId}-enemy`, 1, "dusk")
    ]
  );
  ui.attachGame(fresh);
  ui.renders = [];
  ui.mutations = [];
  ui.logs = [];
  assert.equal(await pending, false);
  assert.equal(target.hp, hp);
  assert.equal(ui.game, fresh);
  assert.deepEqual(ui.renders, []);
  assert.deepEqual(ui.mutations, []);
  assert.deepEqual(ui.logs, []);
});

